<?php
declare(strict_types=1);
namespace Smollan\App;
use PDO; use Smollan\Repositories\OperationsRepository; use Smollan\Services\WorkflowService; use Smollan\Services\ProjectWorkflowService; use Smollan\Support\Auth; use Smollan\Support\Csrf; use Smollan\Support\Database; use Smollan\Support\Env; use Smollan\Support\Http; use Smollan\Support\Policy; use Throwable;
final class Application {
 private ?PDO $pdo=null; private ?string $dbError=null;
 private function db():?PDO {if($this->pdo)return $this->pdo;try{return $this->pdo=Database::connection();}catch(Throwable $e){$this->dbError=$e->getMessage();return null;}}
 public function run():void {
  $path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';
  if(str_starts_with($path,'/assets/')){$this->staticAsset($path);return;}
  if($path==='/health'){header('Content-Type: application/json');echo json_encode(['status'=>'ok','app'=>'SMOLLAN PHP Operations Hub','database_configured'=>(bool)Env::get('DB_HOST')]);return;}
  $pdo=$this->db();
  if($path==='/login'&&Http::method()==='POST'){$this->login($pdo);return;}
  if($path==='/logout'&&Http::method()==='POST'){if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}Auth::logout();Http::redirect('/login');}
  if($path==='/login'){$this->loginPage();return;}
  if(!$pdo){$this->setupPage($this->dbError);return;}
  $route=trim($path,'/');
  if(preg_match('#^reports/share/([A-Za-z0-9_-]{30,})$#',$route,$m)){$this->publicReport($pdo,$m[1]);return;}
  if(preg_match('#^checkin/([A-Za-z0-9_-]{30,})$#',$route,$m)){if(Http::method()==='POST'){$this->publicCheckIn($pdo,$m[1]);return;}$this->publicCheckInPage($pdo,$m[1]);return;}
  if(!Auth::user())Http::redirect('/login');\n  if((Auth::membership()['role']??'')==='promoter'&&!in_array($route,['portal','attendance/check-in','attendance/check-out'],true))Http::redirect('/portal');\n  if($route==='portal'){$this->promoterPortal($pdo);return;}
  if($route===''||$route==='overview'){Policy::requireModule('overview');$this->overview($pdo);return;}
  if($route==='project/create'&&Http::method()==='POST'){$this->createProject($pdo);return;}
  if($route==='promoter/create'&&Http::method()==='POST'){$this->createPromoter($pdo);return;}\n  if(preg_match('#^promoter/([0-9a-f-]{36})/invite$#i',$route,$m)&&Http::method()==='POST'){$this->invitePromoter($pdo,$m[1]);return;}\n  if($route==='store-supervisor/create'&&Http::method()==='POST'){$this->mapStoreSupervisor($pdo);return;}
  if(preg_match('#^project/([0-9a-f-]{36})/(store|assignment|report)$#i',$route,$m)&&Http::method()==='POST'){$this->projectAction($pdo,$m[1],$m[2]);return;}
  if(preg_match('#^assignment/([0-9a-f-]{36})/checkin-link$#i',$route,$m)&&Http::method()==='POST'){$this->createCheckInLink($pdo,$m[1]);return;}
  if(preg_match('#^report/([0-9a-f-]{36})/share$#i',$route,$m)&&Http::method()==='POST'){$this->createReportShare($pdo,$m[1]);return;}
  if(preg_match('#^project-item/(goodies|plv|uniforms)/create$#i',$route,$m)&&Http::method()==='POST'){$this->createProjectItem($pdo,$m[1]);return;}
  if(preg_match('#^projects/([0-9a-f-]{36})$#i',$route,$m)){$this->projectPage($pdo,$m[1]);return;}
  if($route==='quotation/create'&&Http::method()==='POST'){$this->createQuotation($pdo);return;}
  if($route==='expense/create'&&Http::method()==='POST'){$this->createExpense($pdo);return;}
  if(preg_match('#^(expense|resource)/([0-9a-f-]+)/decision$#i',$route,$m)&&Http::method()==='POST'){$this->decide($pdo,$m[1],$m[2]);return;}
  if($route==='attendance/check-in'&&Http::method()==='POST'){$this->checkIn($pdo);return;}
  if($route==='attendance/check-out'&&Http::method()==='POST'){$this->checkOut($pdo);return;}
  $module=$this->routeModule($route);
  if(!$module){http_response_code(404);$this->layout('Not found','<section class="panel"><h2>Page not found</h2><p>The requested module does not exist.</p><a class="button" href="/">Return to overview</a></section>');return;}
  Policy::requireModule($module);$this->modulePage($pdo,$module);
 }
 private function routeModule(string $r):?string{return ['clients'=>'clients','projects'=>'projects','tasks'=>'tasks','promoters'=>'promoters','stores'=>'stores','supervisors'=>'supervisors','attendance'=>'attendance','surveys'=>'surveys','goodies'=>'goodies','posm'=>'posm','uniforms'=>'uniforms','assets'=>'assets','hr'=>'hr','resources'=>'resources','finance'=>'finance','quotations'=>'quotations','procurement'=>'procurement','whatsapp'=>'whatsapp','integrations'=>'integrations','imports'=>'imports','drive'=>'integrations'][$r]??null;}
 private function login(?PDO $pdo):void{
  if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);$this->loginPage('This form expired. Reload and try again.');return;}
  if(!$pdo){$this->loginPage('Database is not configured yet.');return;}
  $email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');
  if(!filter_var($email,FILTER_VALIDATE_EMAIL)){$this->loginPage('Enter a valid email address.');return;}
  try{if(Auth::login($pdo,$email,$password))Http::redirect('/');$this->loginPage('Sign-in was not accepted. Check password, email confirmation, and active administrator-assigned role.');}
  catch(Throwable $e){error_log('SMOLLAN login failure: '.$e->getMessage());$this->loginPage('Sign-in could not complete. Validate Supabase Auth configuration.');}
 }
 private function loginPage(?string $error=null):void{
  $flash=Http::takeFlash();$error=$error??($flash['message']??null);
  $body='<div class="login-grid"><section class="login-brand"><div class="wordmark"><span class="mark">s.</span><div><b>SMOLLAN</b><small>MOROCCO OPERATIONS</small></div></div><div><span class="eyebrow">OPERATIONS CLOUD / PHP + POSTGRESQL</span><h1>One operational truth.<br><em>Every store, team and project.</em></h1><p>Projects, field execution, suppliers, finance and people operations—linked around the activation.</p></div><div class="feature-list"><span>01&nbsp; Project command center</span><span>02&nbsp; Field-team execution & attendance</span><span>03&nbsp; Quotations, purchase requests & payments</span><span>04&nbsp; Secure HR files and private evidence</span></div></section><section class="login-card"><div class="eyebrow">SECURE EMPLOYEE ACCESS</div><h2>Welcome back</h2><p class="muted">SMOLLAN staff use their work email; promoters use the email address from their invitation.</p>'.($error?'<div class="alert warning">'.Http::e($error).'</div>':'').'<form method="post" action="/login">'.Csrf::field().'<label>Work email<input required type="email" name="email" autocomplete="username" placeholder="name@smollan.com"></label><label>Password<input required type="password" name="password" autocomplete="current-password"></label><button class="button primary block">Sign in <span>→</span></button></form><p class="small muted">Access is granted after an administrator activates your role. CIN/RIB/PEC files are private.</p></section></div>';
  $this->layout('Sign in',$body,false);
 }
 private function setupPage(?string $error):void{$body='<div class="setup-wrap"><div class="wordmark"><span class="mark">s.</span><div><b>SMOLLAN</b><small>OPERATIONS PLATFORM</small></div></div><section class="setup-card"><span class="eyebrow">CONFIGURATION CHECK</span><h1>Connect the operations database</h1><p>The PHP application is running, but no live session will be opened until a secure PostgreSQL connection is configured.</p><div class="alert warning">'.Http::e($error??'Database connection not configured').'</div><ol><li>Copy <code>php-app/.env.example</code> to <code>php-app/.env</code>.</li><li>Use Supabase Dashboard → Connect → Session pooler. Add pooler host, database, user and password.</li><li>Use SSL with the Supabase CA certificate and <code>DB_SSLMODE=verify-full</code>.</li><li>Provision a real Auth user and activate their role in <code>smollan_memberships</code> using administrator control.</li></ol><p class="muted small">No demo records are substituted for live records.</p></section></div>';$this->layout('Setup',$body,false);}
 private function overview(PDO $pdo):void{
  $r=new OperationsRepository($pdo);$cards=[['Clients',$r->count('smollan_clients'),'/clients','Accounts and briefs'],['Projects',$r->count('smollan_projects'),'/projects','Delivery portfolios'],['Promoters',$r->count('smollan_promoters'),'/promoters','Roster and eligibility'],['Stores',$r->count('smollan_stores'),'/stores','Retail network'],['Active assignments',$r->count('smollan_assignments',"status='Active'"),'/projects','Active field deployment'],['Attendance pending',$r->count('smollan_attendance',"validation_status='Pending'"),'/attendance','Validation queue'],['Resource requests',$r->count('smollan_resource_requests',"status='Pending'"),'/resources','Approvals needed'],['Unpaid expenses',$r->count('smollan_expenses',"payment_status <> 'Paid'"),'/finance','Finance follow-up']];
  $h='<section class="welcome-row"><div><span class="eyebrow"><span class="live-dot"></span> LIVE DATABASE / MOROCCO</span><h1>Operations overview</h1><p class="muted">The same project connects client brief, field delivery, resources and money.</p></div><div class="welcome-actions"><a class="button primary" href="/projects">Open projects <span>→</span></a></div></section><section class="metrics">';
  foreach($cards as [$l,$n,$href,$hint])$h.='<a class="metric" href="'.$href.'"><span>'.Http::e($l).'</span><strong>'.number_format($n).'</strong><small>'.Http::e($hint).'</small></a>';
  $h.='</section><div class="section-head"><div><span class="eyebrow">WORKSPACE</span><h2>Open a workstream</h2></div></div><section class="module-grid">';
  $mods=[['projects','Projects','Brief, client scope, cities, dates, budget and linked execution'],['tasks','Tasks & teams','Ownership, due dates, dependencies and evidence'],['attendance','Check-in / check-out','Assignment-linked shifts, photos and validation'],['surveys','Surveys & field feedback','Project forms and visit feedback'],['goodies','Goodies / gifts','Stock, project allocation, dispatch and distribution'],['posm','PLV / POSM','Production, suppliers, store dispatch and installation'],['uniforms','Uniforms','SKU stock and issue/return ledger'],['assets','Assets & devices','Serial numbers, MDM, ownership and maintenance'],['resources','PEC & resource requests','PEC, tablet, uniform and IT approval to fulfillment'],['hr','HR files / PEC','Sensitive documents in private storage'],['quotations','Quotation maker','MAD line items and draft quotation'],['procurement','Supplier quotations & PO requests','Supplier comparisons, approvals and receiving'],['finance','Finance & payments','Expenses, invoices, approvals and reconciliation'],['whatsapp','WhatsApp groups','Project/client/city group directory'],['integrations','Google Workspace','Drive, Gmail and Sheets OAuth setup'],['imports','Excel import center','Preview, mapping, dry run and reconciliation']];
  foreach($mods as [$slug,$title,$desc])$h.='<a class="module-tile" href="/'.Http::e($slug).'"><span class="module-icon">'.Http::e(strtoupper(substr($title,0,1))).'</span><span><b>'.Http::e($title).'</b><small>'.Http::e($desc).'</small></span><i>↗</i></a>';
  $h.='</section><section class="info-strip"><div><b>Database-backed</b><p>Counts above query the protected Supabase PostgreSQL database through PHP.</p></div><div><b>Integrations are gated</b><p>Google OAuth and WhatsApp Business require credentials; no messages or external records are fabricated.</p></div></section>';$this->layout('Overview',$h);
 }
 private function modulePage(PDO $pdo,string $module):void{
  $labels=['clients'=>'Clients & briefs','projects'=>'Projects','tasks'=>'Tasks & teams','promoters'=>'Promoters','stores'=>'Stores','supervisors'=>'Supervisors','attendance'=>'Attendance & check-in/out','surveys'=>'Surveys','goodies'=>'Goodies & gifts','posm'=>'PLV / POSM tracker','uniforms'=>'Uniforms & stock','assets'=>'Assets & devices','hr'=>'HR files & PEC','resources'=>'Resource requests & approvals','finance'=>'Expenses, invoices & payments','quotations'=>'Quotation maker','procurement'=>'Supplier quotations & PO requests','whatsapp'=>'WhatsApp group directory','integrations'=>'Google Workspace','imports'=>'Excel import center'];$title=$labels[$module]??ucfirst($module);$r=new OperationsRepository($pdo);$search=trim((string)($_GET['q']??''));$items=[];
  try{$items=$r->rows($module,'created_at',150,$search);}catch(Throwable $e){error_log('SMOLLAN query error: '.$e->getMessage());}
  $h='<section class="welcome-row"><div><span class="eyebrow">SMOLLAN / WORKSTREAM</span><h1>'.Http::e($title).'</h1><p class="muted">Operational records from SMOLLAN database, linked to project and audit context.</p></div>';
  if(in_array($module,['quotations','finance'],true)&&Auth::can('platform_admin','leadership','finance','activation_coordinator'))$h.='<div class="welcome-actions"><a class="button primary" href="#create-form">+ New '.($module==='quotations'?'quotation':'expense').'</a></div>';$h.='</section>';
  if($module==='integrations'){$this->layout($title,$h.$this->integrationSummary());return;}
  if(in_array($module,['procurement','imports','surveys'],true)){$this->layout($title,$h.$this->workflowBoundary($module));return;}
  $h.='<section class="panel"><div class="panel-toolbar"><div><b>Record directory</b><small>'.number_format(count($items)).' rows shown · maximum 150</small></div><form class="search-form" method="get"><input name="q" value="'.Http::e($search).'" placeholder="Search this workstream"><button class="button subtle">Search</button></form></div>'.$this->renderTable($items).'</section>';
  if($module==='quotations')$h.=$this->quotationForm($r);if($module==='finance')$h.=$this->expenseForm($r);if($module==='resources')$h.='<section class="panel"><h2>Approval queue</h2><p class="muted">Actions are server-side and role-gated; pending requests remain separate from fulfillment.</p></section>';$this->layout($title,$h);
 }
 private function renderTable(array $rows):string{if(!$rows)return '<div class="empty"><div class="empty-mark">∅</div><b>No records found</b><p>No rows are visible for this query, or a dedicated workflow form remains to be wired.</p></div>';$keys=array_keys($rows[0]);$hidden=['id','description','notes','private_document_ref','installation_photo_ref','photo_ref','drive_url','group_url','contact_email','contact_phone','serial_number'];$cols=array_values(array_filter($keys,fn($k)=>!in_array($k,$hidden,true)));if(!$cols)$cols=$keys;$h='<div class="table-wrap"><table><thead><tr>';foreach($cols as $k)$h.='<th>'.Http::e(str_replace('_',' ',ucfirst($k))).'</th>';$h.='</tr></thead><tbody>';foreach($rows as $row){$h.='<tr>';foreach($cols as $k){$v=$row[$k]??null;if(in_array($k,['budget','amount','total_amount','unit_value','unit_cost','purchase_cost','actual_amount','budget_amount'],true)&&$v!==null)$v=number_format((float)$v,2,'.',' ').' MAD';$h.='<td>'.Http::e($v??'—').'</td>';}$h.='</tr>';}return $h.'</tbody></table></div>';}
 private function quotationForm(OperationsRepository $r):string{$h='<section class="panel" id="create-form"><div class="section-head"><div><span class="eyebrow">QUOTE BUILDER</span><h2>Create quotation</h2></div></div><p class="muted">Quotation header and line items are saved transactionally; line totals are generated by PostgreSQL.</p><form method="post" action="/quotation/create" id="quotation-form">'.Csrf::field().'<div class="form-grid"><label>Project<select name="project_id" required><option value="">Select project</option>';foreach($r->projectsForSelect() as $p)$h.='<option value="'.Http::e($p['id']).'">'.Http::e($p['name']).'</option>';$h.='</select></label><label>Notes<input name="notes" placeholder="Commercial notes"></label></div><div id="quote-lines"><div class="quote-line"><label>Description<input required name="lines[0][description]"></label><label>Qty<input required min="0.01" step="0.01" type="number" name="lines[0][quantity]" value="1"></label><label>Unit price MAD<input required min="0" step="0.01" type="number" name="lines[0][unit_price]" value="0"></label></div></div><button class="button subtle" type="button" onclick="addQuoteLine()">+ Add line</button> <button class="button primary" type="submit">Save quotation as draft →</button></form></section>';return $h;}
 private function expenseForm(OperationsRepository $r):string{$h='<section class="panel" id="create-form"><div class="section-head"><div><span class="eyebrow">FINANCE INTAKE</span><h2>Submit expense or invoice</h2></div></div><form method="post" action="/expense/create">'.Csrf::field().'<div class="form-grid"><label>Project<select name="project_id" required><option value="">Select project</option>';foreach($r->projectsForSelect() as $p)$h.='<option value="'.Http::e($p['id']).'">'.Http::e($p['name']).'</option>';$h.='</select></label><label>Category<input name="category" required placeholder="Supplier, logistics, payroll…"></label><label>Amount (MAD)<input type="number" name="amount" min="0" step="0.01" required></label><label>Spend type<select name="spend_type"><option>Planned</option><option>Additional</option></select></label><label>Expense date<input type="date" name="expense_date" value="'.date('Y-m-d').'"></label><label>Invoice / receipt ref<input name="receipt_ref"></label><label class="wide">Justification<textarea name="justification"></textarea></label><label class="wide">Notes<textarea name="notes"></textarea></label></div><button class="button primary">Submit for approval →</button></form></section>';return $h;}
 private function createQuotation(PDO $pdo):void{if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}try{$id=(new WorkflowService($pdo))->createQuotation($_POST);Http::flash('success','Quotation saved as draft.');Http::redirect('/quotations#'.$id);}catch(Throwable $e){Http::flash('error',$e->getMessage());Http::redirect('/quotations#create-form');}}
 private function createExpense(PDO $pdo):void{if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}try{$id=(new WorkflowService($pdo))->createExpense($_POST);Http::flash('success','Expense submitted for approval.');Http::redirect('/finance#'.$id);}catch(Throwable $e){Http::flash('error',$e->getMessage());Http::redirect('/finance#create-form');}}
 private function decide(PDO $pdo,string $kind,string $id):void{if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}try{if($kind==='expense')(new WorkflowService($pdo))->decideExpense($id,(string)($_POST['decision']??''),trim((string)($_POST['reason']??''))?:null);else(new WorkflowService($pdo))->decideResource($id,(string)($_POST['decision']??''),trim((string)($_POST['reason']??''))?:null);Http::flash('success','Decision saved and audited.');}catch(Throwable $e){Http::flash('error',$e->getMessage());}Http::redirect($kind==='expense'?'/finance':'/resources');}
 private function checkIn(PDO $pdo):void{if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}try{(new \Smollan\Services\AttendanceService($pdo))->checkIn((string)($_POST['assignment_id']??''),trim((string)($_POST['photo_ref']??''))?:null);Http::flash('success','Check-in saved pending validation.');}catch(Throwable $e){Http::flash('error',$e->getMessage());}Http::redirect('/attendance');}
 private function checkOut(PDO $pdo):void{if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}try{(new \Smollan\Services\AttendanceService($pdo))->checkOut((string)($_POST['attendance_id']??''));Http::flash('success','Check-out saved.');}catch(Throwable $e){Http::flash('error',$e->getMessage());}Http::redirect('/attendance');}
 private function integrationSummary():string{$g=\Smollan\Services\GoogleWorkspace::status();$w=\Smollan\Services\WhatsAppBusiness::status();$h='<section class="metrics"><div class="metric"><span>Google Workspace OAuth</span><strong class="metric-text">'.($g['configured']?'Configured':'Setup required').'</strong><small>Drive, Gmail and Sheets need OAuth consent.</small></div><div class="metric"><span>WhatsApp Business</span><strong class="metric-text">'.($w['configured']?'Configured':'Setup required').'</strong><small>Cloud API credentials, permissions and webhooks are required.</small></div></section><section class="panel"><h2>Google Drive, Gmail and Sheets</h2><p class="muted">Use per-user OAuth, minimal scopes and encrypted refresh tokens.</p><div class="integration-list">';foreach($g['features'] as $x)$h.='<div><b>'.Http::e($x['name']).'</b><span class="status-pill">'.Http::e($x['status']).'</span><p>'.Http::e($x['scope']).'</p></div>';$h.='</div><a class="button subtle" href="https://console.cloud.google.com/apis/credentials" target="_blank" rel="noopener">Google Cloud credentials ↗</a></section><section class="panel"><h2>WhatsApp Business Platform</h2><p>'.Http::e($w['notes']).'</p><p class="muted">Business API messaging is not consumer WhatsApp group automation. Invite links remain a directory unless the business account explicitly supports group operations.</p><a class="button subtle" href="https://developers.facebook.com/docs/whatsapp/cloud-api/" target="_blank" rel="noopener">WhatsApp Cloud API documentation ↗</a></section>';return $h;}
 private function workflowBoundary(string $module):string{$m=['procurement'=>['Supplier quotations & PO requests','Supplier register, quotation comparison, PO numbering, approvals, goods receipt, invoice matching and payment reconciliation need normalized tables before data entry is enabled.'],'imports'=>['Safe import center','Production imports require private staging, worksheet preview, field mapping, duplicate conflict review, dry-run counts and transactional import with row-level results.'],'surveys'=>['Surveys & field feedback','Project-scoped forms, response records, private evidence and supervisor review need assignment-bound authorization and revocable links.']];[$t,$d]=$m[$module];return '<section class="panel"><div class="eyebrow">WORKFLOW BOUNDARY</div><h2>'.Http::e($t).'</h2><p>'.Http::e($d).'</p><p class="muted">This screen accepts no records until end-to-end workflow and access checks are complete.</p></section>';}
 
  private function renderProjectTable(array $rows):string{if(!$rows)return '<div class="empty"><b>No projects found</b><p>Create a project below to start configuring stores, modules, assignments and reports.</p></div>';$h='<div class="table-wrap"><table><thead><tr><th>Code</th><th>Project</th><th>Client</th><th>Status</th><th>Service</th><th></th></tr></thead><tbody>';foreach($rows as $r)$h.='<tr><td>'.Http::e($r['code']??'—').'</td><td><b>'.Http::e($r['name']??'—').'</b></td><td>'.Http::e($r['client_name']??'—').'</td><td>'.Http::e($r['status']??'—').'</td><td>'.Http::e(str_replace('_',' ',$r['service_type']??'—')).'</td><td><a class="button subtle" href="/projects/'.Http::e($r['id']).'">Open dashboard →</a></td></tr>';return $h.'</tbody></table></div>';}
  private function projectCreateForm(PDO $pdo):string{$clients=$pdo->query('select id::text as id,name from public.smollan_clients order by name')->fetchAll(PDO::FETCH_ASSOC);$stores=$pdo->query("select id::text as id,name,city from public.smollan_stores where status='Active' order by city,name limit 1000")->fetchAll(PDO::FETCH_ASSOC);$h='<section class="panel" id="create-project"><div class="section-head"><div><span class="eyebrow">PROJECT SETUP</span><h2>Create project</h2></div></div><p class="muted">Choose modules at creation. Store supervisor mappings are inherited automatically when stores are linked.</p><form method="post" action="/project/create">'.Csrf::field().'<div class="form-grid"><label>Client<select name="client_id" required><option value="">Select client</option>';foreach($clients as $x)$h.='<option value="'.Http::e($x['id']).'">'.Http::e($x['name']).'</option>';$h.='</select></label><label>Project name<input name="name" required maxlength="180"></label><label>Service type<select name="service_type"><option value="activation">Activation</option><option value="permanent_promoters">Permanent promoters</option><option value="production_only">Production only</option><option value="in_store_animation">In-store animation</option><option value="merchandising">Merchandising</option></select></label><label>Cadence<select name="cadence"><option value="none">Not recurring</option><option value="VSD">VSD</option><option value="SD">SD</option></select></label><label>Start date<input type="date" name="start_date"></label><label>End date<input type="date" name="end_date"></label><label>Budget (MAD)<input type="number" min="0" step="0.01" name="budget"></label><label>Cities<input name="cities" placeholder="Casablanca, Rabat, Marrakech"></label></div><div class="field-group"><b>Modules</b><div class="module-picks"><label><input type="checkbox" name="modules[]" value="goodies"> Goodies / gifts</label><label><input type="checkbox" name="modules[]" value="plv"> PLV / POSM</label><label><input type="checkbox" name="modules[]" value="uniforms"> Uniforms</label></div></div><label>Initial stores <span class="muted small">(multi-select)</span><select name="store_ids[]" multiple size="7">';foreach($stores as $x)$h.='<option value="'.Http::e($x['id']).'">'.Http::e($x['name'].' · '.($x['city']??'City not set')).'</option>';$h.='</select></label><button class="button primary">Create project & open dashboard →</button></form></section>';return $h;}
  private function promoterCreateForm():string{return '<section class="panel" id="create-promoter"><div class="section-head"><div><span class="eyebrow">FIELD TEAM</span><h2>Add promoter to recruitment pool</h2></div></div><p class="muted">This saves the personnel record. Supabase login-account provisioning requires a separate server-only Auth Admin credential.</p><form method="post" action="/promoter/create">'.Csrf::field().'<div class="form-grid"><label>Full name<input required name="full_name"></label><label>Phone<input name="phone" type="tel"></label><label>Email<input name="email" type="email"></label><label>City<input name="city"></label><label>Contract type<select name="contract_type"><option>Activation</option><option>Permanent</option><option>Freelance</option></select></label><label class="wide">Notes<textarea name="notes"></textarea></label></div><button class="button primary">Save promoter profile →</button></form></section>';}
  private function projectItemForm(PDO $pdo,string $module):string{$q=$pdo->prepare("select p.id::text as id,p.name from public.smollan_projects p join public.smollan_project_modules m on m.project_id=p.id where m.module_key=:module and m.enabled order by p.name");$q->execute(['module'=>$module]);$projects=$q->fetchAll(PDO::FETCH_ASSOC);if(!$projects)return '<section class="panel"><h2>Project items</h2><p class="muted">No project has enabled this module yet. Enable it in project setup first.</p><a class="button subtle" href="/projects">Open projects →</a></section>';$h='<section class="panel" id="create-item"><div class="section-head"><div><span class="eyebrow">ITEM CONFIGURATION</span><h2>Add '.($module==='plv'?'PLV / POSM material':($module==='goodies'?'goodie / gift':'uniform SKU')).'</h2></div></div><form method="post" action="/project-item/'.Http::e($module).'/create">'.Csrf::field().'<div class="form-grid"><label>Project<select name="project_id" required><option value="">Select project</option>';foreach($projects as $p)$h.='<option value="'.Http::e($p['id']).'">'.Http::e($p['name']).'</option>';$h.='</select></label><label>Item name<input name="name" required></label>';if($module==='goodies')$h.='<label>Category<input name="category"></label><label>Supplier / source<input name="source"></label><label>Quantity<input type="number" min="0" name="quantity" value="0"></label><label>Unit value (MAD)<input type="number" min="0" step="0.01" name="unit_cost" value="0"></label><label>Status<select name="status"><option>Planning</option><option>Ordered</option><option>In Stock</option><option>Dispatched</option></select></label>';elseif($module==='plv')$h.='<label>Material type<input name="material_type" required></label><label>Supplier<input name="source"></label><label>Quantity<input type="number" min="0" name="quantity" value="0"></label><label>Unit cost (MAD)<input type="number" min="0" step="0.01" name="unit_cost" value="0"></label><label>Production deadline<input type="date" name="deadline"></label><label>Status<select name="status"><option>Planning</option><option>In Production</option><option>Ready</option><option>Delivered</option></select></label>';else $h.='<label>SKU code<input name="sku" required></label><label>Size<input name="size"></label><label>Color<input name="color"></label><label>Quantity on hand<input type="number" min="0" name="quantity" value="0"></label><label>Reorder level<input type="number" min="0" name="reorder_level" value="0"></label><label>Unit cost (MAD)<input type="number" min="0" step="0.01" name="unit_cost" value="0"></label>';$h.='<label class="wide">Description / notes<textarea name="description"></textarea></label></div><button class="button primary">Save item →</button></form></section>';return $h;}
  private function projectPage(PDO $pdo,string $projectId):void{try{$d=(new ProjectWorkflowService($pdo))->projectData($projectId);}catch(Throwable $e){Http::flash('error','Project not found or unavailable.');Http::redirect('/projects');return;}$p=$d['project'];$h='<section class="welcome-row"><div><span class="eyebrow">PROJECT COMMAND CENTER / '.Http::e($p['code']).'</span><h1>'.Http::e($p['name']).'</h1><p class="muted">'.Http::e($p['client_name']).' · '.Http::e(str_replace('_',' ',$p['service_type'])).' · '.Http::e($p['status']).'</p></div><a class="button subtle" href="/projects">← All projects</a></section>';$enabled=array_column(array_filter($d['modules'],fn($m)=>in_array($m['enabled'],[true,'t','true',1,'1'],true)),'module_key');$h.='<section class="metrics"><div class="metric"><span>Linked stores</span><strong>'.count($d['stores']).'</strong></div><div class="metric"><span>Active assignments</span><strong>'.count(array_filter($d['assignments'],fn($a)=>$a['status']==='Active')).'</strong></div><div class="metric"><span>Enabled modules</span><strong>'.count($enabled).'</strong><small>'.Http::e($enabled?implode(' · ',$enabled):'No optional modules').'</small></div></section><section class="panel"><div class="section-head"><div><span class="eyebrow">RETAIL FOOTPRINT</span><h2>Stores & supervisors</h2></div></div>';$h.=$d['stores']?'<div class="table-wrap"><table><thead><tr><th>Store</th><th>City</th><th>Supervisor</th><th>Active promoters</th></tr></thead><tbody>':'';foreach($d['stores'] as $s)$h.='<tr><td>'.Http::e($s['store_name']).'</td><td>'.Http::e($s['city']??'—').'</td><td>'.Http::e($s['supervisor_name']??'Not mapped').'</td><td>'.(int)$s['active_promoters'].'</td></tr>';if($d['stores'])$h.='</tbody></table></div>';else $h.='<p class="muted">No stores linked yet.</p>';if(Auth::can('platform_admin','leadership','activation_coordinator','field_manager')){$linked=array_column($d['stores'],'store_id');$stores=$pdo->query("select id::text as id,name,city from public.smollan_stores where status='Active' order by city,name limit 1000")->fetchAll(PDO::FETCH_ASSOC);$h.='<form method="post" action="/project/'.Http::e($projectId).'/store">'.Csrf::field().'<label>Add store<select name="store_id" required><option value="">Choose a store</option>';foreach($stores as $s)if(!in_array($s['id'],$linked,true))$h.='<option value="'.Http::e($s['id']).'">'.Http::e($s['name'].' · '.($s['city']??'')).'</option>';$h.='</select></label><button class="button subtle">Add store & inherit supervisor →</button></form>';}$h.='</section>';
   if(Auth::can('platform_admin','leadership','activation_coordinator','field_manager','field_operations','supervisor')){$promoters=$pdo->query("select id::text as id,full_name,city from public.smollan_promoters where status<>'Inactive' order by full_name limit 2000")->fetchAll(PDO::FETCH_ASSOC);$h.='<section class="panel"><div class="section-head"><div><span class="eyebrow">TEAM ASSIGNMENT</span><h2>Assign promoter to a store</h2></div></div><form method="post" action="/project/'.Http::e($projectId).'/assignment">'.Csrf::field().'<div class="form-grid"><label>Store<select name="store_id" required><option value="">Choose linked store</option>';foreach($d['stores'] as $s)$h.='<option value="'.Http::e($s['store_id']).'">'.Http::e($s['store_name']).'</option>';$h.='</select></label><label>Promoter<select name="promoter_id" required><option value="">Choose promoter</option>';foreach($promoters as $x)$h.='<option value="'.Http::e($x['id']).'">'.Http::e($x['full_name'].' · '.($x['city']??'')).'</option>';$h.='</select></label><label>Start date<input type="date" name="start_date" value="'.date('Y-m-d').'" required></label><label>End date<input type="date" name="end_date"></label></div><button class="button primary">Assign promoter →</button></form>';if($d['assignments']){$h.='<div class="table-wrap"><table><thead><tr><th>Promoter</th><th>Store</th><th>Supervisor</th><th>Period</th><th>Status</th><th>Check-in link</th></tr></thead><tbody>';foreach($d['assignments'] as $a){$h.='<tr><td>'.Http::e($a['full_name']).'</td><td>'.Http::e($a['store_name']).'</td><td>'.Http::e($a['supervisor_name']??'—').'</td><td>'.Http::e($a['start_date'].' → '.($a['end_date']??'ongoing')).'</td><td>'.Http::e($a['status']).'</td><td>';if($a['status']==='Active')$h.='<form method="post" action="/assignment/'.Http::e($a['id']).'/checkin-link">'.Csrf::field().'<button class="button subtle">Create link</button></form>';else $h.='—';$h.='</td></tr>';}$h.='</tbody></table></div>';}$h.='</section>';}
   if(Auth::can('platform_admin','leadership','activation_coordinator','field_manager','field_operations')){$h.='<section class="panel"><div class="section-head"><div><span class="eyebrow">CLIENT REPORTING</span><h2>Project reports</h2></div></div><form method="post" action="/project/'.Http::e($projectId).'/report">'.Csrf::field().'<div class="form-grid"><label>Report title<input name="title" required maxlength="180" placeholder="Weekly activation report"></label><label class="wide">Executive summary<textarea name="summary"></textarea></label></div><button class="button primary">Create report snapshot →</button></form>';if($d['reports']){$h.='<div class="table-wrap"><table><thead><tr><th>Report</th><th>Status</th><th>Created</th><th>Share</th></tr></thead><tbody>';foreach($d['reports'] as $r)$h.='<tr><td><b>'.Http::e($r['title']).'</b><br><small>'.Http::e($r['summary']).'</small></td><td>'.Http::e($r['status']).'</td><td>'.Http::e($r['created_at']).'</td><td><form method="post" action="/report/'.Http::e($r['id']).'/share">'.Csrf::field().'<button class="button subtle">Create client link</button></form></td></tr>';$h.='</tbody></table></div>';}$h.='</section>';}
   if($enabled){$h.='<section class="panel"><h2>Configured modules</h2><p class="muted">Add items from each module page; item forms only show projects that enabled the module.</p><div class="module-picks">';foreach($enabled as $m)$h.='<a class="button subtle" href="/'.($m==='plv'?'posm':$m).'">'.Http::e(strtoupper($m)).' items →</a>';$h.='</div></section>';}$this->layout('Project dashboard',$h);}
  private function createProject(PDO $pdo):void{if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}try{$id=(new ProjectWorkflowService($pdo))->createProject($_POST);Http::flash('success','Project created. Store supervisor mappings are linked automatically.');Http::redirect('/projects/'.$id);}catch(Throwable $e){Http::flash('error',$e->getMessage());Http::redirect('/projects#create-project');}}
  private function createPromoter(PDO $pdo):void{if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}try{(new ProjectWorkflowService($pdo))->createPromoter($_POST);Http::flash('success','Promoter profile saved to recruitment pool. Login account provisioning is separate.');}catch(Throwable $e){Http::flash('error',$e->getMessage());}Http::redirect('/promoters#create-promoter');}
  private function projectAction(PDO $pdo,string $id,string $action):void{if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}try{$s=new ProjectWorkflowService($pdo);if($action==='store'){$s->addStore($id,(string)($_POST['store_id']??''));Http::flash('success','Store added and its mapped supervisor inherited.');}elseif($action==='assignment'){$s->assignPromoter($id,(string)($_POST['store_id']??''),(string)($_POST['promoter_id']??''),(string)($_POST['start_date']??''),trim((string)($_POST['end_date']??''))?:null);Http::flash('success','Promoter assigned with the store supervisor attached.');}else{$s->createReport($id,(string)($_POST['title']??''),(string)($_POST['summary']??''));Http::flash('success','Published report snapshot created. Create a client share link below.');}}catch(Throwable $e){Http::flash('error',$e->getMessage());}Http::redirect('/projects/'.$id);}
  private function createProjectItem(PDO $pdo,string $module):void{if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}$id=(string)($_POST['project_id']??'');try{(new ProjectWorkflowService($pdo))->createProjectItem($module,$_POST);Http::flash('success','Project item saved.');}catch(Throwable $e){Http::flash('error',$e->getMessage());}Http::redirect('/projects/'.$id);}
  private function publicReport(PDO $pdo,string $token):void{$r=(new ProjectWorkflowService($pdo))->publicReport($token);if(!$r){http_response_code(404);$this->layout('Report unavailable','<section class="panel"><h1>Report link unavailable</h1><p>This report link may have expired or been revoked.</p></section>',false);return;}$metrics=$r['metrics'];$h='<div class="setup-wrap"><div class="wordmark"><span class="mark">s.</span><div><b>SMOLLAN</b><small>CLIENT REPORT</small></div></div><section class="setup-card"><span class="eyebrow">'.Http::e($r['project_code']).' / CLIENT REPORT</span><h1>'.Http::e($r['title']).'</h1><p class="muted">'.Http::e($r['project_name']).'</p><p>'.nl2br(Http::e($r['summary'])).'</p><section class="metrics">';foreach(['stores'=>'Linked stores','active_assignments'=>'Active promoters','attendance_today'=>'Attendance today','goodies_items'=>'Goodies items','plv_items'=>'PLV items'] as $k=>$label)$h.='<div class="metric"><span>'.Http::e($label).'</span><strong>'.(int)($metrics[$k]??0).'</strong></div>';$h.='</section><p class="small muted">Shared read-only report · SMOLLAN Morocco</p></section></div>';$this->layout('Client report',$h,false);}
  private function publicCheckInPage(PDO $pdo,string $token):void{$r=(new ProjectWorkflowService($pdo))->resolveAttendanceLink($token);if(!$r){http_response_code(410);$this->layout('Check-in unavailable','<section class="setup-card"><h1>Check-in link expired</h1><p>Ask your supervisor for a new link.</p></section>',false);return;}$h='<div class="setup-wrap"><div class="wordmark"><span class="mark">s.</span><div><b>SMOLLAN</b><small>PROMOTER CHECK-IN</small></div></div><section class="setup-card"><span class="eyebrow">ASSIGNMENT CHECK-IN</span><h1>Welcome, '.Http::e($r['full_name']).'</h1><p class="muted">'.Http::e($r['project_name']).' · '.Http::e($r['store_name']).'</p><p>Submit attendance for today. This single-use link expires automatically; check-in remains pending supervisor validation.</p><form method="post" action="/checkin/'.Http::e($token).'">'.Csrf::field().'<label>Optional private photo reference<input name="photo_ref"></label><button class="button primary">Confirm check-in →</button></form></section></div>';$this->layout('Promoter check-in',$h,false);}
  private function publicCheckIn(PDO $pdo,string $token):void{if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}try{(new ProjectWorkflowService($pdo))->checkInWithLink($token,trim((string)($_POST['photo_ref']??''))?:null);$this->layout('Check-in saved','<div class="setup-wrap"><section class="setup-card"><h1>Check-in saved</h1><p>Attendance was submitted and is waiting for supervisor validation.</p></section></div>',false);}catch(Throwable $e){http_response_code(410);$this->layout('Check-in unavailable','<section class="setup-card"><h1>Check-in not completed</h1><p>'.Http::e($e->getMessage()).'</p></section>',false);}}
  private function createCheckInLink(PDO $pdo,string $id):void{if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}try{$token=(new ProjectWorkflowService($pdo))->createAttendanceLink($id);$this->shareLinkPage('Promoter check-in link',$this->absoluteUrl('/checkin/'.$token),'Single-use link expires in 14 days. Send it directly to the assigned promoter.');}catch(Throwable $e){Http::flash('error',$e->getMessage());Http::redirect('/projects');}}
  private function createReportShare(PDO $pdo,string $id):void{if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}try{$token=(new ProjectWorkflowService($pdo))->createReportShare($id);$this->shareLinkPage('Client report link',$this->absoluteUrl('/reports/share/'.$token),'Read-only link valid for 30 days. Treat it as confidential.');}catch(Throwable $e){Http::flash('error',$e->getMessage());Http::redirect('/projects');}}
  private function absoluteUrl(string $path):string{$base=rtrim((string)Env::get('APP_BASE_URL',''),'/');if($base!=='')return $base.$path;$host=(string)($_SERVER['HTTP_HOST']??'');if(!preg_match('/^[a-zA-Z0-9.-]+(?::[0-9]{1,5})?$/',$host))throw new \RuntimeException('Set APP_BASE_URL to create shareable links.');return 'https://'.$host.$path;}
  private function shareLinkPage(string $title,string $url,string $note):void{$h='<section class="panel"><span class="eyebrow">LINK CREATED</span><h1>'.Http::e($title).'</h1><p>'.Http::e($note).'</p><label>Copy link<input readonly value="'.Http::e($url).'" onclick="this.select()"></label><p><a class="button primary" href="'.Http::e($url).'" target="_blank" rel="noopener">Open link ↗</a> <a class="button subtle" href="/projects">Back to projects</a></p></section>';$this->layout($title,$h);}

  private function renderPromoterTable(PDO $pdo,array $rows):string{if(!$rows)return $this->renderTable($rows);$h='<div class="table-wrap"><table><thead><tr><th>Name</th><th>Phone</th><th>Email</th><th>City</th><th>Status</th><th>Login</th></tr></thead><tbody>';foreach($rows as $r){$q=$pdo->prepare('select user_id::text from public.smollan_promoters where id=cast(:id as uuid)');$q->execute(['id'=>$r['id']]);$userId=$q->fetchColumn();$h.='<tr><td>'.Http::e($r['full_name']??'—').'</td><td>'.Http::e($r['phone']??'—').'</td><td>'.Http::e($r['email']??'—').'</td><td>'.Http::e($r['city']??'—').'</td><td>'.Http::e($r['status']??'—').'</td><td>';if($userId)$h.='<span class="status-pill">Account linked</span>';elseif(!empty($r['email'])&&Auth::can('platform_admin','leadership','activation_coordinator','field_manager','hr_coordinator'))$h.='<form method="post" action="/promoter/'.Http::e($r['id']).'/invite">'.Csrf::field().'<button class="button subtle">Email login invite</button></form>';else $h.='<span class="muted small">Add email</span>';$h.='</td></tr>'; }return $h.'</tbody></table></div>';}
  private function storeSupervisorForm(PDO $pdo):string{$stores=$pdo->query("select id::text as id,name,city from public.smollan_stores where status='Active' order by name")->fetchAll(PDO::FETCH_ASSOC);$supers=$pdo->query("select id::text as id,full_name,city from public.smollan_supervisors where status='Active' order by full_name")->fetchAll(PDO::FETCH_ASSOC);$h='<section class="panel"><div class="section-head"><div><span class="eyebrow">AUTOMATIC PROJECT ROUTING</span><h2>Map supervisors to stores</h2></div></div><p class="muted">When a mapped store is added to a project, its primary supervisor is assigned automatically.</p><form method="post" action="/store-supervisor/create">'.Csrf::field().'<div class="form-grid"><label>Store<select name="store_id" required><option value="">Choose store</option>';foreach($stores as $s)$h.='<option value="'.Http::e($s['id']).'">'.Http::e($s['name'].' · '.($s['city']??'')).'</option>';$h.='</select></label><label>Supervisor<select name="supervisor_id" required><option value="">Choose supervisor</option>';foreach($supers as $s)$h.='<option value="'.Http::e($s['id']).'">'.Http::e($s['full_name'].' · '.($s['city']??'')).'</option>';$h.='</select></label></div><label><input type="checkbox" name="is_primary" value="1" checked> Set as primary supervisor for this store</label><button class="button primary">Save store supervisor mapping →</button></form></section>';return $h;}
  private function mapStoreSupervisor(PDO $pdo):void{if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}try{(new ProjectWorkflowService($pdo))->mapSupervisorToStore((string)($_POST['store_id']??''),(string)($_POST['supervisor_id']??''),isset($_POST['is_primary']));Http::flash('success','Store supervisor mapping saved. Existing project-store links without a supervisor were updated.');}catch(Throwable $e){Http::flash('error',$e->getMessage());}Http::redirect('/supervisors');}
  private function invitePromoter(PDO $pdo,string $id):void{if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}try{(new ProjectWorkflowService($pdo))->invitePromoter($id);Http::flash('success','Supabase invitation sent. The promoter can set their password from the invite email.');}catch(Throwable $e){Http::flash('error',$e->getMessage());}Http::redirect('/promoters');}
  private function promoterPortal(PDO $pdo):void{$uid=(string)(Auth::user()['id']??'');$q=$pdo->prepare("select id::text,full_name from public.smollan_promoters where user_id=cast(:id as uuid) and status<>'Inactive'");$q->execute(['id'=>$uid]);$p=$q->fetch(PDO::FETCH_ASSOC);if(!$p){Auth::logout();Http::redirect('/login');return;}$q=$pdo->prepare("select a.id::text as assignment_id,a.start_date,a.end_date,pr.name as project_name,s.name as store_name,s.city,(select at.id::text from public.smollan_attendance at where at.assignment_id=a.id and at.attendance_date=current_date limit 1) as attendance_id,(select at.check_in from public.smollan_attendance at where at.assignment_id=a.id and at.attendance_date=current_date limit 1) as check_in,(select at.check_out from public.smollan_attendance at where at.assignment_id=a.id and at.attendance_date=current_date limit 1) as check_out from public.smollan_assignments a join public.smollan_projects pr on pr.id=a.project_id join public.smollan_stores s on s.id=a.store_id where a.promoter_id=cast(:promoter as uuid) and a.status='Active' and a.start_date<=current_date and (a.end_date is null or a.end_date>=current_date) order by pr.name,s.name");$q->execute(['promoter'=>$p['id']]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);$h='<section class="welcome-row"><div><span class="eyebrow">PROMOTER SELF-SERVICE</span><h1>Hello, '.Http::e($p['full_name']).'</h1><p class="muted">Your active assignments and attendance for today.</p></div></section>';if(!$rows)$h.='<section class="panel"><h2>No active assignments</h2><p class="muted">Contact your supervisor if this is unexpected.</p></section>';foreach($rows as $a){$h.='<section class="panel"><h2>'.Http::e($a['project_name']).'</h2><p class="muted">'.Http::e($a['store_name'].' · '.($a['city']??'')).'</p><p>Shift: '.Http::e($a['start_date'].' → '.($a['end_date']??'ongoing')).'</p>';if(empty($a['check_in']))$h.='<form method="post" action="/attendance/check-in">'.Csrf::field().'<input type="hidden" name="assignment_id" value="'.Http::e($a['assignment_id']).'"><button class="button primary">Check in now →</button></form>';elseif(empty($a['check_out']))$h.='<p class="status-pill">Checked in at '.Http::e($a['check_in']).'</p><form method="post" action="/attendance/check-out">'.Csrf::field().'<input type="hidden" name="attendance_id" value="'.Http::e($a['attendance_id']).'"><button class="button primary">Check out →</button></form>';else $h.='<p class="status-pill">Shift completed · '.Http::e($a['check_out']).'</p>';$h.='</section>';}$this->layout('Promoter portal',$h);}
private function layout(string $title,string $body,bool $authenticated=true):void{header('Content-Type: text/html; charset=utf-8');header('X-Content-Type-Options: nosniff');header('Referrer-Policy: strict-origin-when-cross-origin');header('Permissions-Policy: camera=(self), geolocation=(), microphone=()');header("Content-Security-Policy: default-src 'self'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com; script-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; base-uri 'self'; frame-ancestors 'none'; form-action 'self'");$u=Auth::user();$m=Auth::membership();$flash=Http::takeFlash();echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#102b38"><title>'.Http::e($title).' · SMOLLAN Operations</title><link rel="stylesheet" href="/assets/app.css"></head><body>';
  if($authenticated&&$u){$nav=[['overview','Overview'],['clients','Clients'],['projects','Projects'],['tasks','Tasks'],['promoters','Promoters'],['stores','Stores'],['supervisors','Supervisors'],['attendance','Attendance'],['surveys','Surveys'],['goodies','Goodies'],['posm','PLV / POSM'],['uniforms','Uniforms'],['assets','Assets'],['hr','HR / PEC'],['resources','Requests'],['quotations','Quotations'],['procurement','Supplier POs'],['finance','Finance'],['whatsapp','WhatsApp groups'],['integrations','Google Workspace'],['imports','Import center']];echo '<aside class="sidebar"><a class="wordmark" href="/"><span class="mark">s.</span><span><b>SMOLLAN</b><small>MOROCCO OPERATIONS</small></span></a><div class="workspace"><span class="workspace-indicator"></span><div><b>Operations workspace</b><small>All activations · MAD</small></div></div><div class="nav-heading">WORKSPACE</div><nav>';foreach($nav as [$slug,$label])if(Policy::allows($slug==='overview'?'overview':($slug==='integrations'?'integrations':$slug)))echo '<a class="nav-link'.(trim(parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH),'/')===$slug?' current':'').'" href="/'.Http::e($slug).'"><span class="nav-glyph">'.Http::e(substr($label,0,1)).'</span>'.Http::e($label).'</a>';echo '</nav><div class="side-bottom"><small>PRIVATE OPERATIONS DATA</small><span>PostgreSQL · RLS enabled</span></div></aside><main class="main"><header class="topbar"><div><span class="crumb">SMOLLAN / </span><b>'.Http::e($title).'</b></div><div class="top-user"><span class="avatar">'.Http::e(strtoupper(substr($u['email']??'SM',0,1))).'</span><div><b>'.Http::e($u['email']??'SMOLLAN User').'</b><small>'.Http::e(str_replace('_',' ',$m['role']??'member')).'</small></div><form action="/logout" method="post">'.Csrf::field().'<button class="logout">Sign out</button></form></div></header><div class="content">';}
  if($flash)echo '<div class="alert '.Http::e($flash['type']??'info').'">'.Http::e($flash['message']??'').'</div>';echo $body;if($authenticated&&$u)echo '</div><footer>SMOLLAN Morocco · Confidential operational data · '.date('Y').'</footer></main>';echo '<script src="/assets/app.js" defer></script></body></html>';}
 private function staticAsset(string $path):void{$file=realpath(dirname(__DIR__).'/public'.$path);$base=realpath(dirname(__DIR__).'/public/assets');if(!$file||!$base||!str_starts_with($file,$base)||!is_file($file)){http_response_code(404);exit;}$ext=pathinfo($file,PATHINFO_EXTENSION);header('Content-Type: '.($ext==='css'?'text/css':($ext==='js'?'application/javascript':'application/octet-stream')));readfile($file);}
